configuration.tbelDecoder:
// 1. Decodifica nativa del payload con i metodi built-in di ThingsBoard
var data = decodeToJson(payload);

// Se decodeToJson restituisce null (es. se payload era già una stringa o byte raw)
if (!data) {
    try {
        var str = payloadBytesToString(payload);
        data = JSON.parse(str);
    } catch (e) {
        data = {};
    }
}

// 2. Estrazione del livello dati (gestisce sia JSON annidato sotto 'payload' che diretto)
var p = (data && data.payload) ? data.payload : data;

// 3. Estrazione dei sotto-oggetti
var hw = p.hw || {};
var analysis = p.analysis || {};
var ram = hw.ram || {};
var disk = hw.disk || {};

// 4. Mappatura della telemetria pulita
var cleanTelemetry = {
    spore_count: Number(analysis.spore_count || 0),
    detected: analysis.detected ? 1 : 0,
    frame_id: Number(p.frame_id || 0),
    sample_id: String(p.sample_id || ""),
    
    // Diagnostica Hardware
    cpu_temp_c: Number(hw.cpu_temp_c || 0),
    processing_time_s: Number(hw.processing_time_s || 0),
    ram_used_percent: Number(ram.used_percent || 0),
    disk_used_percent: Number(disk.used_percent || 0)
};

// 5. Estrazione dinamica del nome dispositivo o fallback a sensore_001
var devName = String(p.device_id || "sensore_001");

// 6. Ritorno della struttura valida per l'Integrazione
return {
   deviceName: devName,
   deviceType: "Optical Biosensor",
   telemetry: cleanTelemetry
};
